import gurobipy as gp
from gurobipy import GRB
products = []
revenue = {}
demand = {}
init_inventory = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    pid = v['Product Name']
    products.append(pid)
    try:
        revenue[pid] = float(v['Revenue'])
        demand[pid] = int(v['Demand'])
        init_inventory[pid] = int(v['Initial Inventory'])
    except Exception as e:
        raise ValueError(f'Invalid data for product {pid}: {e}')
for pid in products:
    if pid not in revenue or pid not in demand or pid not in init_inventory:
        raise ValueError(f'Missing data for product {pid}')
m = gp.Model('Supermarket_Fulfillment')
x = m.addVars(products, lb=0, ub={pid: min(demand[pid], init_inventory[pid]) for pid in products}, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[pid] * x[pid] for pid in products)), GRB.MAXIMIZE)
m.addConstrs((x[pid] <= min(demand[pid], init_inventory[pid]) for pid in products), name='')
m.addConstrs((x[pid] >= 0 for pid in products), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')